package gg.offerbook.sync;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("offerbooksync")
public interface OfferbookSyncConfig extends Config
{
	@ConfigItem(
		keyName = "apiToken",
		name = "Offerbook token",
		description = "Paste a token from offerbook.gg → Account → Connect RuneLite. "
			+ "This plugin sends your Grand Exchange offer events (item, price, quantity, "
			+ "state, timestamp) to offerbook.gg to power your automatic flip journal. "
			+ "Tokens are write-only and revocable at any time.",
		secret = true,
		position = 0
	)
	default String apiToken()
	{
		return "";
	}
}

package gg.offerbook.sync;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.io.IOException;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.task.Schedule;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Offerbook Sync: read-only Grand Exchange offer sync for offerbook.gg.
 *
 * Captures GrandExchangeOfferChanged lifecycle events (placement price,
 * partial fills, cancellation, completion) and batches them to the user's
 * Offerbook account to power the automatic flip journal. Strictly read-only:
 * no menu entries, no actions sent to the game server, no automation.
 *
 * Privacy: nothing is sent until the user pastes a token; the config panel
 * discloses exactly what is transmitted; the token is write-only and
 * revocable; the account identifier is RuneLite's opaque account hash, and
 * display names never leave the machine.
 */
@Slf4j
@PluginDescriptor(
	name = "Offerbook Sync",
	description = "Sends your GE offer events (item, price, quantity, state) to offerbook.gg for your automatic flip journal",
	tags = {"grand", "exchange", "flipping", "ge", "journal", "offerbook"}
)
public class OfferbookSyncPlugin extends Plugin
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	/**
	 * Fixed, not user-editable: a configurable endpoint would let anyone who can
	 * change a player's config redirect their trade history to another server.
	 */
	private static final String INGEST_URL = "https://offerbook.gg/api/ingest/trades";
	private static final int MAX_BATCH = 100;
	private static final int MAX_QUEUE = 2000;

	@Inject
	private Client client;

	@Inject
	private OfferbookSyncConfig config;

	@Inject
	private OkHttpClient httpClient;

	@Inject
	private Gson gson;

	private final ConcurrentLinkedQueue<Map<String, Object>> queue = new ConcurrentLinkedQueue<>();

	/**
	 * One id per offer instance, keyed by account+slot and minted when a slot
	 * goes from empty to occupied. RuneLite replays the state of every occupied
	 * slot on login, so without a stable key the server cannot tell a relog
	 * replay of a completed offer from a second, identical trade.
	 */
	private final Map<String, String> offerKeys = new ConcurrentHashMap<>();

	@Provides
	OfferbookSyncConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OfferbookSyncConfig.class);
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		long rawHash = client.getAccountHash();
		if (rawHash == -1)
		{
			// Not logged in yet: there is no account to attribute this event to.
			return;
		}

		GrandExchangeOffer offer = event.getOffer();
		String accountHash = Long.toHexString(rawHash);
		String slotKey = accountHash + ":" + event.getSlot();
		if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY || offer.getItemId() <= 0)
		{
			// The slot was collected or cleared: the next offer here is a new one.
			offerKeys.remove(slotKey);
			return;
		}

		Map<String, Object> e = new HashMap<>();
		e.put("itemId", offer.getItemId());
		e.put("slot", event.getSlot());
		e.put("side", isBuy(offer.getState()) ? "buy" : "sell");
		e.put("status", mapStatus(offer.getState()));
		e.put("price", offer.getPrice());
		e.put("quantity", offer.getTotalQuantity());
		e.put("filledQuantity", offer.getQuantitySold());
		e.put("spent", offer.getSpent());
		e.put("clientTs", System.currentTimeMillis());
		e.put("accountHash", accountHash);
		e.put("offerKey", offerKeys.computeIfAbsent(slotKey, k -> UUID.randomUUID().toString()));
		queue.add(e);
		trimQueue();
	}

	/**
	 * Bound the queue rather than growing without limit while offline; the
	 * oldest states are the ones a later snapshot already supersedes.
	 */
	private void trimQueue()
	{
		while (queue.size() > MAX_QUEUE)
		{
			queue.poll();
		}
	}

	@Schedule(period = 10, unit = ChronoUnit.SECONDS, asynchronous = true)
	public void flush()
	{
		String token = config.apiToken();
		if (token == null || token.isEmpty() || queue.isEmpty())
		{
			return;
		}

		List<Map<String, Object>> batch = new ArrayList<>();
		Map<String, Object> next;
		while (batch.size() < MAX_BATCH && (next = queue.poll()) != null)
		{
			batch.add(next);
		}
		if (batch.isEmpty())
		{
			return;
		}

		Map<String, Object> body = new HashMap<>();
		body.put("events", batch);

		Request request = new Request.Builder()
			.url(INGEST_URL)
			.header("Authorization", "Bearer " + token)
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				// Put the batch back so a network blip doesn't leave a hole in the
				// journal. Re-sends are safe: the server keys each row by offer
				// instance and ignores repeats.
				log.debug("offerbook sync failed, requeueing {} events: {}", batch.size(), e.getMessage());
				queue.addAll(batch);
				trimQueue();
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try
				{
					// 401 means the token was revoked and retrying cannot help;
					// 429 and 5xx are transient, so those events are kept.
					if (response.code() == 429 || response.code() >= 500)
					{
						queue.addAll(batch);
						trimQueue();
					}
				}
				finally
				{
					response.close();
				}
			}
		});
	}

	private static boolean isBuy(GrandExchangeOfferState state)
	{
		switch (state)
		{
			case BUYING:
			case BOUGHT:
			case CANCELLED_BUY:
				return true;
			default:
				return false;
		}
	}

	private static String mapStatus(GrandExchangeOfferState state)
	{
		switch (state)
		{
			case BUYING:
				return "BUYING";
			case BOUGHT:
				return "BOUGHT";
			case CANCELLED_BUY:
				return "CANCELLED_BUY";
			case SELLING:
				return "SELLING";
			case SOLD:
				return "SOLD";
			case CANCELLED_SELL:
				return "CANCELLED_SELL";
			default:
				return "PENDING";
		}
	}
}

package gg.offerbook.sync;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Local dev runner: launches a full RuneLite client with the plugin loaded.
 * Not part of the Plugin Hub build.
 */
public class OfferbookSyncPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(OfferbookSyncPlugin.class);
		RuneLite.main(args);
	}
}
